      const cs = getComputedStyle(root);
      return { harnessWidth: h.width, rootWidth: r.width, gridColumn: cs.gridColumn };
    });
    info.gridMeasurements = measurements;
  }

  if (s.id.includes('default')) {
    const textInfo = await page.evaluate(() => {
      const p = document.querySelector('p');
      const btn = document.querySelector('a[role="button"], button, a');
      const cs = p ? getComputedStyle(p) : null;
      return {
        text: p?.textContent,
        fontSize: cs?.fontSize,
        color: cs?.color,
        ctaText: btn?.textContent,
        ctaHref: btn?.getAttribute('href'),
      };
    });
    info.defaultInfo = textInfo;
  }

  results[s.name] = info;
  await page.close();
}

await browser.close();
console.log(JSON.stringify(results, null, 2));
